/* HOF Pulse ERP — shared design tokens, icons, and primitives.
   Visual source of truth: Figma "HOF CRM Redesign" file, Claude Feeder section. */

const T = {
  blue: '#1869EC', blueLight:'#EAF2FE',
  black:'#000000', gray800:'#1A1A1A', gray600:'#5B5B5B', gray400:'#949494',
  border:'#EEEEEE', borderStrong:'#E4E4E4',
  surface:'#FFFFFF', pageBg:'#FAFBFC', headerBg:'#FAFAFA',
  red:'#D92D20',

  /* Attio design-system tokens — sampled directly from the Attio reference frame in Figma
     ("Companies | All Companies - Attio", node 6280:9409): 36px rows, hairline #EEEFF1 grid
     lines on both axes, near-black body text, muted column headers, and a slightly cooler
     blue for link-style values. Scoped to the Contacts grid so the rest of the app keeps the
     brand tokens above unchanged. */
  attioLine:'#EEEFF1', attioText:'#15141B', attioMuted:'#6B6A70',
  attioFaint:'#A4A4A9', attioBlue:'#2B6DF1', attioRowH:36,

  /* Deal temperature, shown on Board cards. Only Hot and Warm render; Low / no temperature
     shows nothing. How a temperature is decided is NOT defined yet — these are just the two
     colours the indicator uses once a value exists. */
  hot:'#D9480F', warm:'#B25E09',
  /* Pass / below-threshold states for score KPIs (Contact Overview). */
  good:'#0E9F6E',

  /* One size for every dropdown/disclosure chevron, so they can't drift apart again. Note the
     nominal size is not the mark you see: Phosphor's caret inks only 176x96 of its 256 box, so
     the previous size of 8 rendered a caret just 5.5x3px — hence how faint it looked. At 14 the
     caret is ~9.6x5.3px, readable while still sitting under the 15-16px UI icons around it. */
  chevronSize:14,
};

/* One consistent icon library used across the whole UI — Phosphor Icons (regular weight),
   https://phosphoricons.com, MIT. Chosen to match the Figma reference (node 6280:11094): soft
   rounded terminals and generous corner radii instead of the sharp, geometric line set used
   before. Every glyph comes from that one library at one weight, so stroke weight, proportions,
   corner treatment and visual density are consistent by construction rather than by hand.

   Phosphor draws its outlines as *filled* shapes on a 256 grid (the rounding is baked into the
   geometry), so these render with `fill` rather than `stroke` — which is why the `strokeWidth`
   prop below is inert. The uniform weight it used to control is now inherent to the set.

   Deliberately NOT covered here: the main ERP screen's module tiles, which keep their
   hand-drawn blue/black Streamline-Freehand artwork via `ModuleIcon` (moduleIcons.jsx), and the
   designer-supplied `sidebarCollapse` glyph special-cased in `Icon` below. */
