  const z = useFloatZ(!!pos);
  const [month, setMonth] = React.useState(null);   // the month shown: Date (1st of the month)
  const inputRef = React.useRef(null), panelRef = React.useRef(null);
  const PANEL_H = 296, PANEL_W = 264;
  React.useEffect(() => { if(document.activeElement !== inputRef.current) setText(dateLabel(value)); }, [value]);
  const typed = text.trim() ? parseDate(text) : null;
  const invalid = !!text.trim() && !typed;
  const shown = typed || value;
  const monthOf = (v) => { const d = fromYmd(v) || new Date(); return new Date(d.getFullYear(), d.getMonth(), 1); };
  // The calendar follows what's typed while it reads as a date.
