    const first = month.getDay(), days = new Date(month.getFullYear(), month.getMonth() + 1, 0).getDate();
    for(let i = 0; i < first; i++) cells.push(null);
    for(let d = 1; d <= days; d++) cells.push(ymd(new Date(month.getFullYear(), month.getMonth(), d)));
