/* Date & time — the date field and the time field side by side. The value is "YYYY-MM-DDTHH:MM",
   like a native date-time input: it's set once both parts are (until then, empty). */
function DateTimeField({value, onChange, inputStyle, required, ariaLabel}){
  const split = (v) => { const [d, t] = String(v || '').split('T'); return {date:d || '', time:(t || '').slice(0, 5)}; };
  const [parts, setParts] = React.useState(() => split(value));
  React.useEffect(() => { if(value) setParts(split(value)); }, [value]);
  const set = (patch) => {
    const next = {...parts, ...patch};
    setParts(next);
    const v = next.date && next.time ? `${next.date}T${next.time}` : '';
    if(v !== (value || '')) onChange(v);
  };
  return (
    // Side by side; in a narrow slot (a half-width form field) the time wraps under the date.
    <div style={{display:'flex', flexWrap:'wrap', gap:8, minWidth:0}}>
      <div style={{flex:'1.4 1 150px', minWidth:0, display:'flex'}}><DateField value={parts.date} onChange={(d)=>set({date:d})} inputStyle={inputStyle} required={required} ariaLabel={ariaLabel ? `${ariaLabel} date` : 'Date'}/></div>
      <div style={{flex:'1 1 110px', minWidth:0, display:'flex'}}><TimeField value={parts.time} onChange={(t)=>set({time:t})} inputStyle={inputStyle} required={required && !!parts.time} ariaLabel={ariaLabel ? `${ariaLabel} time` : 'Time'}/></div>
    </div>
  );
}

/* Placeholder panel for controls whose behaviour has not been specified yet. Shared so the
   same 'not defined yet' treatment is used everywhere instead of being re-invented. */
function StubPanel({title, onClose, zIndex=90}){
  return (
    <div style={{position:'fixed', inset:0, zIndex}} onClick={onClose}>
      <div style={{position:'absolute', inset:0, background:'rgba(16,24,40,.25)'}}/>
      <div onClick={e=>e.stopPropagation()} style={{position:'absolute', top:80, right:24, width:320, background:'#fff', borderRadius:10, boxShadow:'0 8px 24px rgba(16,24,40,.16)'}}>
        <div style={{display:'flex', alignItems:'center', justifyContent:'space-between', padding:'14px 16px', borderBottom:`1px solid ${T.border}`}}>
          <span style={{fontSize:14, fontWeight:600, color:T.gray800}}>{title}</span>
          <button onClick={onClose} style={{border:'none', background:'transparent', cursor:'pointer', color:T.gray600, display:'flex'}}><Icon name="close" size={12} color={T.gray600}/></button>
        </div>
        <div style={{padding:'20px 16px', fontSize:13, color:T.gray400}}>Not defined yet.</div>
      </div>
    </div>
  );
}

